388	// For use in NPM transition.
389	static bool shouldForceLegacyPM() {
390	  for (const PassInfo *P : PassList) {
391	    StringRef Arg = P->getPassArgument();
392	    if (shouldPinPassToLegacyPM(Arg))
393	      return true;
394	  }
395	  return false;
396	}
